<script setup lang="ts">
import {computed} from 'vue'
import type {VoucherRecord,VoucherFilters} from '../voucher-analysis'
import {voucherInsights} from '../voucher-insights'
import {voucherIncomeChange} from '../voucher-income'
const props=defineProps<{records:VoucherRecord[];kind:'education'|'kindergarten';date:string;filters:VoucherFilters;relatedRecords:VoucherRecord[]}>()
const emit=defineEmits<{drill:[name:string,ids:string[],month?:string]}>()
const data=computed(()=>voucherInsights(props.records,props.date,props.filters,props.relatedRecords)),m=computed(()=>data.value.metrics)
const money=(n:number|null)=>n===null?'Ma’lumot yo‘q':Math.round(n).toLocaleString('uz-UZ')+' so‘m',pct=(n:number|null)=>n===null?'—':n+'%'
const ids=computed(()=>props.records.map(r=>r.id)),trend=computed(()=>data.value.trend.slice(-12)),maxAmount=computed(()=>Math.max(1,...trend.value.map(x=>x.amount??0)))
const income=computed(()=>[{label:'O‘sish',count:m.value.incomeUp,tone:'good',ids:props.records.filter(r=>(voucherIncomeChange(r.income)??0)>0).map(r=>r.id)},{label:'Kamayish',count:m.value.incomeDown,tone:'danger',ids:props.records.filter(r=>(voucherIncomeChange(r.income)??0)<0).map(r=>r.id)},{label:'O‘zgarmagan',count:m.value.incomeSame,tone:'muted',ids:props.records.filter(r=>voucherIncomeChange(r.income)===0).map(r=>r.id)},{label:'Ma’lumot yo‘q',count:m.value.incomeUnknown,tone:'warning',ids:props.records.filter(r=>voucherIncomeChange(r.income)===null).map(r=>r.id)}])
const usageWidth=(n:number)=>m.value.vouchers?n/m.value.vouchers*100:0
const open=(name:string,rows:string[],month?:string)=>emit('drill',name,rows,month)
</script>
<template>
<section class="voucher-insights voucher-print-surface" aria-label="Tahliliy ma’lumotlar">
<div class="vi-heading"><b>Tanlangan davr tahlili</b><b class="vi-print-title">{{ kind==='education'?'To‘garak vaucherlari':'Bog‘cha vaucherlari' }}</b><span>{{ date }} holatiga · {{ m.vouchers }} vaucher · {{ m.children }} bola</span></div>
<div class="vi-kpis">
<button @click="open('Barcha vaucherlar',ids)"><span>Vaucherlar / bolalar</span><strong>{{ m.vouchers }} / {{ m.children }}</strong><small>{{ m.families }} oila · {{ m.organizations }} tashkilot</small></button>
<button @click="open('Faollashgan vaucherlar',records.filter(r=>r.start).map(r=>r.id))"><span>Faollashganlar ulushi</span><strong class="good">{{ pct(m.activationRate) }}</strong><small>{{ m.activated }} / {{ m.vouchers }} vaucher</small></button>
<button @click="open('To‘lovlar',ids)"><span>{{ kind==='education'?'To‘garak uchun to‘langan':'Qoplangan mablag‘' }}</span><strong>{{ money(m.amount) }}</strong><small v-if="kind==='education'">Yo‘lkira: {{ money(m.travel) }}</small><small v-else>Ma’lum davomat: {{ m.attendance??'—' }} kun</small></button>
<button @click="open('Oylik ma’lumot yetishmaydi',data.risks[2]!.ids)"><span>Oylik ma’lumot qamrovi</span><strong :class="m.coverage===null?'muted':m.coverage<70?'danger':m.coverage<100?'warning':'good'">{{ pct(m.coverage) }}</strong><small>{{ m.reported }} / {{ m.expected }} yakunlangan oy</small></button>
</div>
<div class="vi-two">
<section class="vi-panel"><header><h3>Foydalanish darajasi</h3><span>Vaucherlar kesimida</span></header><div class="vi-bars"><button v-for="g in data.usageGroups" :key="g.name" :disabled="!g.ids.length" @click="open(g.name,g.ids)"><span>{{ g.name }}</span><b>{{ g.ids.length }}</b><i><em :class="g.tone" :style="{width:usageWidth(g.ids.length)+'%'}" /></i></button></div><p>Vaucher bahosi yakunlangan oylar ma’lumoti to‘liq bo‘lsa hisoblanadi.</p></section>
<section class="vi-panel"><header><h3>Ma’lumot sifati</h3><span>Vaucher–oy kesimida</span></header><div class="vi-quality"><div><b class="good">{{ m.paidMonths }}</b><span>To‘lov bor oylar</span></div><div><b class="warning">{{ m.zeroMonths }}</b><span>Nol to‘lovli oylar</span></div><div><b class="danger">{{ m.missingMonths }}</b><span>Ma’lumoti yo‘q oylar</span></div></div><div class="vi-quality-footer"><span>Ma’lum oylar bo‘yicha foydalanish</span><b>{{ pct(m.usage) }}</b></div><p>{{ m.paidMonths }} to‘lovli / {{ m.reported }} ma’lum oy. Joriy va kelajak oylar bahoga kirmaydi.</p></section>
</div>
<section class="vi-panel"><header><h3>To‘lovlar dinamikasi</h3><span>Oxirgi {{ trend.length }} hisob oyi · tanlangan davr</span></header><div class="vi-trend" role="group" aria-label="Oylar bo‘yicha qoplangan mablag‘"><button v-for="t in trend" :key="t.month" @click="open(t.month,t.ids,t.month)" :title="t.month+': '+money(t.amount)"><b>{{ t.amount===null?'—':Math.round(t.amount/1000).toLocaleString('uz-UZ') }}</b><i><em :class="{'no-data':t.amount===null}" :style="{height:Math.max(t.amount===null?4:t.amount===0?1:4,(t.amount??0)/maxAmount*100)+'%'}" /></i><span>{{ t.month }}</span></button></div><p>Grafik qiymatlari ming so‘mda. «—» — summa kelmagan, nol summa alohida saqlanadi.</p></section>
<div class="vi-two">
<section class="vi-panel"><header><h3>Hududlar bo‘yicha qamrov</h3><span>Joriy tashkilot hududi</span></header><div class="kg-table"><table><thead><tr><th>Hudud</th><th>Vaucher</th><th>Qamrov</th><th>To‘lov</th></tr></thead><tbody><tr v-for="g in data.regions" :key="g.key"><td><button @click="open(g.name,g.ids)">{{ g.name }}</button></td><td>{{ g.metrics.vouchers }}</td><td :class="g.metrics.coverage===null?'muted':g.metrics.coverage<70?'danger':g.metrics.coverage<100?'warning':'good'">{{ pct(g.metrics.coverage) }}<small>{{ g.metrics.reported }} / {{ g.metrics.expected }} oy</small></td><td>{{ money(g.metrics.amount) }}</td></tr></tbody></table></div></section>
<section class="vi-panel"><header><h3>Nazorat talab qiladigan holatlar</h3><span>Bir vaucher bir necha holatga tushishi mumkin</span></header><div class="vi-risk-list"><button v-for="g in data.risks" :key="g.name" :class="g.tone" :disabled="!g.ids.length" @click="open(g.name,g.ids)"><span>{{ g.name }}</span><b>{{ g.ids.length }}</b></button></div><p>Uzoq kutish chegarasi — {{ filters.waitingDays }} kun. Bu belgilar ko‘rib chiqish uchun, tasdiqlangan qoidabuzarlik emas.</p></section>
</div>
<div class="vi-two">
<section class="vi-panel"><header><h3>{{ kind==='education'?'Ikki fan vaucherlari holati':'Faollashtirish va kutish' }}</h3><span>{{ kind==='education'?'Bola va reja kesimida':'Kunlarda' }}</span></header><template v-if="kind==='education'"><div class="vi-risk-list"><button v-for="g in data.pairGroups" :key="g.name" :disabled="!g.ids.length" @click="open(g.name,g.ids)"><span>{{ g.name }}</span><b>{{ g.children }} bola</b></button></div></template><div v-else class="vi-quality"><div><b>{{ m.activationDays??'—' }}</b><span>O‘rtacha faollashish</span></div><div><b class="warning">{{ m.waitDays??'—' }}</b><span>O‘rtacha kutish</span></div><div><b class="warning">{{ m.longWaiting }}</b><span>Uzoq kutayotgan vaucher</span></div></div><p v-if="kind==='education'">Filterda bitta vaucher qolsa, ikkinchisining holati taxmin qilinmaydi.</p></section>
<section class="vi-panel"><header><h3>Daromad o‘zgarishi</h3><span>Noyob bolalar kesimida</span></header><div class="vi-income-grid"><button v-for="g in income" :key="g.label" :class="g.tone" :disabled="!g.ids.length" @click="open('Daromad: '+g.label,g.ids)"><b>{{ g.count }}</b><span>{{ g.label }}</span></button></div><p>Berilgan paytdagi daromad bilan solishtirilgan. O‘sish vaucherning bevosita natijasi deb olinmaydi.</p></section>
</div>
<section class="vi-panel"><header><h3>Oilaviy iqtisod · {{ data.family.month }}</h3><span>Ikkala xizmat birgalikda</span></header><div class="vi-quality"><div><b>{{ data.family.count }}</b><span>Hisobga olingan oilalar</span></div><div><b class="good">{{ money(data.family.amount) }}</b><span>Ma’lum oilaviy iqtisod</span></div><div><b>{{ data.family.crossService }}</b><span>Bog‘cha va to‘garakdan foydalanayotgan</span></div><div><b class="warning">{{ data.family.incomplete }}</b><span>Ma’lumoti to‘liq bo‘lmagan oilalar</span></div></div><p>Tanlangan vaucherlarga tegishli oilalar bir martadan olinadi. Summaga oilaning boshqa xizmatdagi farzandlari ham kiradi; yuqoridagi xizmat to‘loviga qo‘shib jamlanmaydi.</p><div class="kg-table"><table><thead><tr><th>Oiladagi farzandlar</th><th>Vaucher</th><th>Ma’lum jami</th><th>Jon boshiga</th><th>Ma’lumoti yo‘q</th></tr></thead><tbody><tr v-for="g in data.family.items" :key="g.familyId"><td>{{ [...new Set(g.items.map(i=>i.name))].join(' / ') }}</td><td>{{ g.vouchers }}</td><td>{{ money(g.knownTotal) }}</td><td>{{ money(g.perPerson) }}<small v-if="g.percent!==null">{{ g.missing?'Kamida ':'' }}{{ g.percent }}%</small></td><td :class="g.missing?'warning':'good'">{{ g.missing }}</td></tr><tr v-if="!data.family.items.length"><td colspan="5">Bu oy uchun oilaviy iqtisod ma’lumoti yo‘q.</td></tr></tbody></table></div></section>
<section class="vi-panel"><header><h3>{{ kind==='education'?'Fanlar bo‘yicha tahlil':'Tashkilotlar bo‘yicha to‘lovlar' }}</h3><span>{{ kind==='education'?'Joriy fan':'Joriy tashkilot kesimi' }}</span></header><div class="kg-table"><table><thead><tr><th>{{ kind==='education'?'Fan':'Tashkilot' }}</th><th>Vaucher</th><th>Bola</th><th>Xizmat to‘lovi</th><th>Foydalanish</th><th>Qamrov</th><th>O‘zgargan</th></tr></thead><tbody><tr v-for="g in kind==='education'?data.subjects:data.organizations" :key="g.key"><td><button @click="open(g.name,g.ids)">{{ g.name }}</button></td><td>{{ g.metrics.vouchers }}</td><td>{{ g.metrics.children }}</td><td>{{ money(g.metrics.amount) }}</td><td>{{ pct(g.metrics.usage) }}</td><td>{{ pct(g.metrics.coverage) }}</td><td>{{ g.metrics.changed }}</td></tr></tbody></table></div><p>Summalar vaucher kesimida; tarixiy to‘lovlar tashkilot yoki fanlar o‘rtasida taqsimlanmagan.</p></section>
<p v-if="!m.vouchers" class="vi-empty">Tanlangan filterlar bo‘yicha tahlil uchun ma’lumot topilmadi.</p>
</section>
</template>
